import{_ as t,o as a,c as r,a3 as s}from"./chunks/framework.CasHb79G.js";const c=JSON.parse('{"title":"Profile and settings","description":"","frontmatter":{},"headers":[],"relativePath":"docs/profile-and-settings.md","filePath":"docs/profile-and-settings.md"}'),n={name:"docs/profile-and-settings.md"};function i(o,e,d,h,l,u){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="profile-and-settings" tabindex="-1">Profile and settings <a class="header-anchor" href="#profile-and-settings" aria-label="Permalink to &quot;Profile and settings&quot;">​</a></h1><p>This page defines the profile fields, body-measurement history, units and pain or rehab behavior. The agreed screen layouts and states live in the <a href="https://tkint.github.io/coach-poulpy/mockups/" target="_blank" rel="noreferrer">Mockups gallery</a>, rather than being repeated here (<a href="./adr/0016-mockups-are-plain-html-in-the-repo">ADR 0016</a>). Wording rules are in <a href="./brand#inclusive-by-default">Inclusive by default</a>.</p><h2 id="profile-fields" tabindex="-1">Profile fields <a class="header-anchor" href="#profile-fields" aria-label="Permalink to &quot;Profile fields&quot;">​</a></h2><p>Everything is optional and stays on the phone. Each field is only here because something uses it.</p><table tabindex="0"><thead><tr><th>Field</th><th>Used for</th><th>Notes</th></tr></thead><tbody><tr><td>Display name</td><td>Poulpy&#39;s lines and the share card</td><td>Default: none, Poulpy says &quot;you&quot;</td></tr><tr><td>Birthdate</td><td>Age, and the heart rate zones</td><td>Age is computed, never stored</td></tr><tr><td>Pronouns</td><td>French agreement and Poulpy&#39;s lines. A select; choosing Custom shows a text field beneath it</td><td>She / her, He / him, They / them, Just my name, Custom (typed by the person) or Prefer not to say. Default neutral; a custom entry is repeated as written and never drives French agreement</td></tr><tr><td>Sex assigned at birth</td><td>Calorie and heart rate estimates only</td><td>Female, Male, Intersex, Prefer not to say. Skipped means a neutral average</td></tr><tr><td>Height, weight</td><td>Estimates, and the charts</td><td>Logged over time, below</td></tr><tr><td>Main goal</td><td>Which workouts Poulpy suggests first</td><td>Stay active, Build strength, Run further, Rehab, Something else</td></tr><tr><td>Experience</td><td>Starting loads and plan suggestions</td><td>Just starting, Regular, Experienced</td></tr><tr><td>Resting heart rate</td><td>Heart rate zones</td><td>Typed, or read from a band later</td></tr><tr><td>Body figure</td><td>Which body map is drawn for pain and for the muscles an exercise or a workout works</td><td>Wider shoulders or Wider hips, so the names describe the drawing and say nothing about gender. It is a drawing only: separate from sex assigned at birth, never used for estimates, and never asked as gender</td></tr><tr><td>Pain or rehab</td><td>Poulpy&#39;s blue side for the chosen time</td><td>Where it hurts, on the body map, and for how long; see <a href="./brand#character-rules">Character rules</a></td></tr></tbody></table><p>Suggested for later, not drawn: maximum heart rate override, weekly goal in sessions, dominant side, equipment at home (already a filter), waist and body-fat as optional measurements.</p><h3 id="why-sex-assigned-at-birth" tabindex="-1">Why &quot;sex assigned at birth&quot; <a class="header-anchor" href="#why-sex-assigned-at-birth" aria-label="Permalink to &quot;Why &quot;sex assigned at birth&quot;&quot;">​</a></h3><p>The only thing the app needs is a physiological input for estimates, so that is all it asks, and it names it as what it is: assigned at birth, not &quot;biological&quot; or &quot;birth&quot; sex, and not gender. Intersex is offered and Prefer not to say is always available. Gender is never asked, because no feature needs it. See <a href="./brand-decisions#13-inclusive-by-default">decision 13</a> for what was set aside. This wording comes from published inclusive-forms guidance and has not yet been read by LGBTQ+ people; that read is still to do and does not block building.</p><h2 id="weight-and-height-logging" tabindex="-1">Weight and height logging <a class="header-anchor" href="#weight-and-height-logging" aria-label="Permalink to &quot;Weight and height logging&quot;">​</a></h2><ul><li>Each entry is a date and a value, added from the <strong>Log</strong> button and corrected or deleted from the history list. One entry per day; a second one that day replaces it.</li><li>Height changes slowly, so its screen says a measure every few months is plenty, and teenagers can log as often as they like.</li><li>A weight going up is never red and going down is never green. Poulpy says nothing about it, there is no BMI and no weight goal unless a later issue adds one the person opts into.</li><li>Every chart has a text alternative naming its first and last value.</li></ul><h2 id="units" tabindex="-1">Units <a class="header-anchor" href="#units" aria-label="Permalink to &quot;Units&quot;">​</a></h2><p>The unit system chosen in Settings decides how weight (kg or lb), height (cm or ft and in) and distance (km or mi) are shown and typed. Everything is stored metric, so switching converts and never rewrites; see <a href="./adr/0017-body-measurements-are-stored-metric-and-shown-in-the-persons-units">ADR 0017</a>.</p><h2 id="pain-or-rehab" tabindex="-1">Pain or rehab <a class="header-anchor" href="#pain-or-rehab" aria-label="Permalink to &quot;Pain or rehab&quot;">​</a></h2><p>A person can say where it hurts and choose how long the pain window lasts: 72 hours by default, 1 week, 2 weeks or until they clear it. During that window Poulpy stays on the blue side in the Patched up pose, entries never count as missed, and workouts are never filtered. The body map and its accessibility requirements are defined in the <a href="./design-system#components">design system</a>; the two body figures are chosen independently of sex assigned at birth and are never used for estimates. See <a href="./brand#character-rules">Character rules</a>.</p><h2 id="still-open" tabindex="-1">Still open <a class="header-anchor" href="#still-open" aria-label="Permalink to &quot;Still open&quot;">​</a></h2><ol><li>Who reads the sex assigned at birth and pronoun wording from the community (see <a href="./brand-decisions#13-inclusive-by-default">decision 13</a>).</li><li>Should an optional weight goal line exist later, given the no-judgement rule?</li></ol>',16)])])}const p=t(n,[["render",i]]);export{c as __pageData,p as default};
